//! Title code with C++ exception handling, as MSVC lays it out for
//! `__CxxFrameHandler3`: each function names the handler in its unwind info
//! (`.seh_*` directives) with its `FuncInfo`'s RVA as the handler data, and
//! the tables (unwind map, try blocks, handlers, ip-to-state map) say which
//! `catch` is around which instruction and what to destroy on the way out.
//! The throws call `_CxxThrowException` with a `ThrowInfo` of `int`.
//! Written in assembly so that the states, and the tables, are exactly
//! these.

use core::arch::global_asm;

/// What `probe_cxx_throw_int` throws: its argument.
static mut PROBE_CXX_OBJECT: u32 = 0;
/// The int the last `catch(int)` funclet of the outer functions caught.
#[unsafe(no_mangle)]
pub static mut PROBE_CXX_CAUGHT: u32 = 0;
/// How many times `probe_cxx_unwind`'s destructor ran.
#[unsafe(no_mangle)]
pub static mut PROBE_CXX_DESTROYED: u32 = 0;
/// The int `probe_cxx_rethrow`'s inner function caught.
#[unsafe(no_mangle)]
pub static mut PROBE_CXX_INNER: u32 = 0;

// One block, so that its labels are one object's. First the type `int` as
// a throw names it: a `TypeDescriptor` (`.H`), one `CatchableType` (simple,
// 4 bytes, no copy constructor), its array, and a `ThrowInfo` with no
// destructor.
global_asm!(
    ".section .rdata,\"dr\"",
    ".p2align 3",
    "probe_cxx_td_int:",
    "    .quad 0",
    "    .quad 0",
    "    .asciz \".H\"",
    ".p2align 2",
    "probe_cxx_ct_int:",
    // properties (CT_IsSimpleType), type, PMD { 0, -1, 0 }, size, copy.
    "    .long 1",
    "    .long probe_cxx_td_int@IMGREL",
    "    .long 0, -1, 0",
    "    .long 4",
    "    .long 0",
    "probe_cxx_cta_int:",
    "    .long 1",
    "    .long probe_cxx_ct_int@IMGREL",
    "probe_cxx_ti_int:",
    // attributes, destructor, forward compat, catchable type array.
    "    .long 0, 0, 0",
    "    .long probe_cxx_cta_int@IMGREL",
    // Exported by name: the linker takes these as /EXPORT options.
    ".section .drectve,\"yn\"",
    ".ascii \" /EXPORT:probe_cxx_throw_int /EXPORT:probe_cxx_catch_int\"",
    ".ascii \" /EXPORT:probe_cxx_unwind /EXPORT:probe_cxx_rethrow\"",
    ".ascii \" /EXPORT:probe_cxx_uncaught\"",
    ".text",
    // `object = value; throw object;` (`_CxxThrowException(&object,
    // &ThrowInfo(int))`).
    ".globl probe_cxx_throw_int",
    ".p2align 4",
    "probe_cxx_throw_int:",
    ".seh_proc probe_cxx_throw_int",
    "    sub rsp, 40",
    ".seh_stackalloc 40",
    ".seh_endprologue",
    "    mov dword ptr [rip + {object}], ecx",
    "    lea rcx, [rip + {object}]",
    "    lea rdx, [rip + probe_cxx_ti_int]",
    "    call qword ptr [rip + __imp__CxxThrowException]",
    "    int3",
    ".seh_endproc",
    // `probe_cxx_throw_int(value)` with nothing around it to catch.
    ".globl probe_cxx_uncaught",
    ".p2align 4",
    "probe_cxx_uncaught:",
    ".seh_proc probe_cxx_uncaught",
    "    sub rsp, 40",
    ".seh_stackalloc 40",
    ".seh_endprologue",
    "    call probe_cxx_throw_int",
    "    nop",
    "    add rsp, 40",
    "    ret",
    ".seh_endproc",
    // `if (!value) return 7; try { probe_cxx_throw_int(value); } catch (int
    // e) { caught = e; } return 0x100 + caught;`, the 0x100 kept in rbx
    // across the catch. The frame: the catch object at +0x20, the
    // unwind-help slot at +0x28.
    ".globl probe_cxx_catch_int",
    ".p2align 4",
    "probe_cxx_catch_int:",
    ".seh_proc probe_cxx_catch_int",
    ".seh_handler {handler}, @unwind, @except",
    "    push rbx",
    ".seh_pushreg rbx",
    "    sub rsp, 0x40",
    ".seh_stackalloc 0x40",
    ".seh_endprologue",
    "    mov qword ptr [rsp + 0x28], -2",
    "    mov ebx, 0x100",
    "    mov eax, 7",
    "    test ecx, ecx",
    "    jz probe_cxx_catch_int_done",
    "probe_cxx_catch_int_try:",
    "    call probe_cxx_throw_int",
    "    nop",
    "probe_cxx_catch_int_after:",
    "    xor eax, eax",
    "    jmp probe_cxx_catch_int_done",
    "probe_cxx_catch_int_cont:",
    "    mov eax, dword ptr [rip + {caught}]",
    "    add eax, ebx",
    "probe_cxx_catch_int_done:",
    "    add rsp, 0x40",
    "    pop rbx",
    "    ret",
    ".seh_handlerdata",
    "    .long probe_cxx_catch_int_fi@IMGREL",
    ".text",
    ".seh_endproc",
    // Its catch funclet (rdx: the frame): the caught int from the catch
    // object, and the continuation.
    ".p2align 4",
    "probe_cxx_catch_int_funclet:",
    ".seh_proc probe_cxx_catch_int_funclet",
    ".seh_endprologue",
    "    mov eax, dword ptr [rdx + 0x20]",
    "    mov dword ptr [rip + {caught}], eax",
    "    lea rax, [rip + probe_cxx_catch_int_cont]",
    "    ret",
    ".seh_endproc",
    // `if (!value) return 7; try { Object o; probe_cxx_throw_int(value); }
    // catch (...) {} return 0x200 + destroyed;`: state 0 the try, 1 with
    // the object alive, whose destructor (an unwind funclet) counts.
    ".globl probe_cxx_unwind",
    ".p2align 4",
    "probe_cxx_unwind:",
    ".seh_proc probe_cxx_unwind",
    ".seh_handler {handler}, @unwind, @except",
    "    push rbx",
    ".seh_pushreg rbx",
    "    sub rsp, 0x40",
    ".seh_stackalloc 0x40",
    ".seh_endprologue",
    "    mov qword ptr [rsp + 0x28], -2",
    "    mov ebx, 0x200",
    "    mov eax, 7",
    "    test ecx, ecx",
    "    jz probe_cxx_unwind_done",
    "probe_cxx_unwind_try:",
    "    mov dword ptr [rsp + 0x30], ecx",
    "probe_cxx_unwind_object:",
    "    call probe_cxx_throw_int",
    "    nop",
    "probe_cxx_unwind_after:",
    "    xor eax, eax",
    "    jmp probe_cxx_unwind_done",
    "probe_cxx_unwind_cont:",
    "    mov eax, dword ptr [rip + {destroyed}]",
    "    add eax, ebx",
    "probe_cxx_unwind_done:",
    "    add rsp, 0x40",
    "    pop rbx",
    "    ret",
    ".seh_handlerdata",
    "    .long probe_cxx_unwind_fi@IMGREL",
    ".text",
    ".seh_endproc",
    ".p2align 4",
    "probe_cxx_unwind_funclet:",
    ".seh_proc probe_cxx_unwind_funclet",
    ".seh_endprologue",
    "    lea rax, [rip + probe_cxx_unwind_cont]",
    "    ret",
    ".seh_endproc",
    // The object's destructor.
    ".p2align 4",
    "probe_cxx_unwind_dtor:",
    ".seh_proc probe_cxx_unwind_dtor",
    ".seh_endprologue",
    "    inc dword ptr [rip + {destroyed}]",
    "    ret",
    ".seh_endproc",
    // The inner function of `probe_cxx_rethrow`: `try {
    // probe_cxx_throw_int(value); } catch (int e) { inner = e; } throw
    // object;` (the same object and type, thrown again after the catch
    // ended, from the body).
    ".p2align 4",
    "probe_cxx_rethrow_inner:",
    ".seh_proc probe_cxx_rethrow_inner",
    ".seh_handler {handler}, @unwind, @except",
    "    push rbx",
    ".seh_pushreg rbx",
    "    sub rsp, 0x40",
    ".seh_stackalloc 0x40",
    ".seh_endprologue",
    "    mov qword ptr [rsp + 0x28], -2",
    "probe_cxx_rethrow_inner_try:",
    "    call probe_cxx_throw_int",
    "    nop",
    "probe_cxx_rethrow_inner_after:",
    "    xor eax, eax",
    "    jmp probe_cxx_rethrow_inner_done",
    "probe_cxx_rethrow_inner_cont:",
    "    lea rcx, [rip + {object}]",
    "    lea rdx, [rip + probe_cxx_ti_int]",
    "    call qword ptr [rip + __imp__CxxThrowException]",
    "    int3",
    "probe_cxx_rethrow_inner_done:",
    "    add rsp, 0x40",
    "    pop rbx",
    "    ret",
    ".seh_handlerdata",
    "    .long probe_cxx_rethrow_inner_fi@IMGREL",
    ".text",
    ".seh_endproc",
    ".p2align 4",
    "probe_cxx_rethrow_inner_funclet:",
    ".seh_proc probe_cxx_rethrow_inner_funclet",
    ".seh_endprologue",
    "    mov eax, dword ptr [rdx + 0x20]",
    "    mov dword ptr [rip + {inner}], eax",
    "    lea rax, [rip + probe_cxx_rethrow_inner_cont]",
    "    ret",
    ".seh_endproc",
    // `if (!value) return 7; try { probe_cxx_rethrow_inner(value); } catch
    // (int e) { caught = e; } return 0x300 + caught;`.
    ".globl probe_cxx_rethrow",
    ".p2align 4",
    "probe_cxx_rethrow:",
    ".seh_proc probe_cxx_rethrow",
    ".seh_handler {handler}, @unwind, @except",
    "    push rbx",
    ".seh_pushreg rbx",
    "    sub rsp, 0x40",
    ".seh_stackalloc 0x40",
    ".seh_endprologue",
    "    mov qword ptr [rsp + 0x28], -2",
    "    mov ebx, 0x300",
    "    mov eax, 7",
    "    test ecx, ecx",
    "    jz probe_cxx_rethrow_done",
    "probe_cxx_rethrow_try:",
    "    call probe_cxx_rethrow_inner",
    "    nop",
    "probe_cxx_rethrow_after:",
    "    xor eax, eax",
    "    jmp probe_cxx_rethrow_done",
    "probe_cxx_rethrow_cont:",
    "    mov eax, dword ptr [rip + {caught}]",
    "    add eax, ebx",
    "probe_cxx_rethrow_done:",
    "    add rsp, 0x40",
    "    pop rbx",
    "    ret",
    ".seh_handlerdata",
    "    .long probe_cxx_rethrow_fi@IMGREL",
    ".text",
    ".seh_endproc",
    ".p2align 4",
    "probe_cxx_rethrow_funclet:",
    ".seh_proc probe_cxx_rethrow_funclet",
    ".seh_endprologue",
    "    mov eax, dword ptr [rdx + 0x20]",
    "    mov dword ptr [rip + {caught}], eax",
    "    lea rax, [rip + probe_cxx_rethrow_cont]",
    "    ret",
    ".seh_endproc",
    // The `FuncInfo`s (magic 0x19930522, /EHs): { magic, max state, unwind
    // map, try blocks, their map, ip map entries, the map, unwind-help slot,
    // exception-spec list, flags }. Unwind map entries are { to state,
    // action }; try blocks { low, high, catch high, catches, handlers };
    // handlers { adjectives, type, catch object, funclet, frame }; ip map
    // entries { RVA, state }, by address.
    ".section .rdata,\"dr\"",
    ".p2align 2",
    // probe_cxx_catch_int: state 0 the try, 1 the catch.
    "probe_cxx_catch_int_fi:",
    "    .long 0x19930522, 2",
    "    .long probe_cxx_catch_int_unwind@IMGREL",
    "    .long 1",
    "    .long probe_cxx_catch_int_tries@IMGREL",
    "    .long 4",
    "    .long probe_cxx_catch_int_ip@IMGREL",
    "    .long 0x28, 0, 1",
    "probe_cxx_catch_int_unwind:",
    "    .long -1, 0",
    "    .long -1, 0",
    "probe_cxx_catch_int_tries:",
    "    .long 0, 0, 1, 1",
    "    .long probe_cxx_catch_int_handlers@IMGREL",
    "probe_cxx_catch_int_handlers:",
    "    .long 0",
    "    .long probe_cxx_td_int@IMGREL",
    "    .long 0x20",
    "    .long probe_cxx_catch_int_funclet@IMGREL",
    "    .long 0",
    "probe_cxx_catch_int_ip:",
    "    .long probe_cxx_catch_int@IMGREL, -1",
    "    .long probe_cxx_catch_int_try@IMGREL, 0",
    "    .long probe_cxx_catch_int_after@IMGREL, -1",
    "    .long probe_cxx_catch_int_funclet@IMGREL, 1",
    // probe_cxx_unwind: 0 the try, 1 the object (its destructor), 2 the
    // catch, `catch(...)` (no type, HT_IsStdDotDot).
    "probe_cxx_unwind_fi:",
    "    .long 0x19930522, 3",
    "    .long probe_cxx_unwind_unwind@IMGREL",
    "    .long 1",
    "    .long probe_cxx_unwind_tries@IMGREL",
    "    .long 6",
    "    .long probe_cxx_unwind_ip@IMGREL",
    "    .long 0x28, 0, 1",
    "probe_cxx_unwind_unwind:",
    "    .long -1, 0",
    "    .long 0",
    "    .long probe_cxx_unwind_dtor@IMGREL",
    "    .long -1, 0",
    "probe_cxx_unwind_tries:",
    "    .long 0, 1, 2, 1",
    "    .long probe_cxx_unwind_handlers@IMGREL",
    "probe_cxx_unwind_handlers:",
    "    .long 0x40, 0, 0",
    "    .long probe_cxx_unwind_funclet@IMGREL",
    "    .long 0",
    "probe_cxx_unwind_ip:",
    "    .long probe_cxx_unwind@IMGREL, -1",
    "    .long probe_cxx_unwind_try@IMGREL, 0",
    "    .long probe_cxx_unwind_object@IMGREL, 1",
    "    .long probe_cxx_unwind_after@IMGREL, -1",
    "    .long probe_cxx_unwind_funclet@IMGREL, 2",
    "    .long probe_cxx_unwind_dtor@IMGREL, -1",
    // probe_cxx_rethrow_inner: as probe_cxx_catch_int.
    "probe_cxx_rethrow_inner_fi:",
    "    .long 0x19930522, 2",
    "    .long probe_cxx_catch_int_unwind@IMGREL",
    "    .long 1",
    "    .long probe_cxx_rethrow_inner_tries@IMGREL",
    "    .long 4",
    "    .long probe_cxx_rethrow_inner_ip@IMGREL",
    "    .long 0x28, 0, 1",
    "probe_cxx_rethrow_inner_tries:",
    "    .long 0, 0, 1, 1",
    "    .long probe_cxx_rethrow_inner_handlers@IMGREL",
    "probe_cxx_rethrow_inner_handlers:",
    "    .long 0",
    "    .long probe_cxx_td_int@IMGREL",
    "    .long 0x20",
    "    .long probe_cxx_rethrow_inner_funclet@IMGREL",
    "    .long 0",
    "probe_cxx_rethrow_inner_ip:",
    "    .long probe_cxx_rethrow_inner@IMGREL, -1",
    "    .long probe_cxx_rethrow_inner_try@IMGREL, 0",
    "    .long probe_cxx_rethrow_inner_after@IMGREL, -1",
    "    .long probe_cxx_rethrow_inner_funclet@IMGREL, 1",
    // probe_cxx_rethrow: as probe_cxx_catch_int.
    "probe_cxx_rethrow_fi:",
    "    .long 0x19930522, 2",
    "    .long probe_cxx_catch_int_unwind@IMGREL",
    "    .long 1",
    "    .long probe_cxx_rethrow_tries@IMGREL",
    "    .long 4",
    "    .long probe_cxx_rethrow_ip@IMGREL",
    "    .long 0x28, 0, 1",
    "probe_cxx_rethrow_tries:",
    "    .long 0, 0, 1, 1",
    "    .long probe_cxx_rethrow_handlers@IMGREL",
    "probe_cxx_rethrow_handlers:",
    "    .long 0",
    "    .long probe_cxx_td_int@IMGREL",
    "    .long 0x20",
    "    .long probe_cxx_rethrow_funclet@IMGREL",
    "    .long 0",
    "probe_cxx_rethrow_ip:",
    "    .long probe_cxx_rethrow@IMGREL, -1",
    "    .long probe_cxx_rethrow_try@IMGREL, 0",
    "    .long probe_cxx_rethrow_after@IMGREL, -1",
    "    .long probe_cxx_rethrow_funclet@IMGREL, 1",
    ".text",
    handler = sym crate::__CxxFrameHandler3,
    object = sym PROBE_CXX_OBJECT,
    caught = sym PROBE_CXX_CAUGHT,
    destroyed = sym PROBE_CXX_DESTROYED,
    inner = sym PROBE_CXX_INNER,
);
